// Normalize data from either Webhook or Manual/Set Trigger
const body = $json.body || {};

const recipient = {
  name: body.recipient?.name || $json.recipient?.name || 'Utilisateur',
  email: body.recipient?.email || $json.recipient?.email || 'user@example.com'
};

const notification = {
  title: body.notification?.title || $json.notification?.title || 'Notification My-Task',
  message: body.notification?.message || $json.notification?.message || 'Vous avez reçu une mise à jour sur votre espace.'
};

const actionUrl = body.actionUrl || $json.actionUrl || 'http://localhost:3000';

return {
  json: {
    recipient,
    notification,
    actionUrl
  }
};

